import sys
import csv
import json
import re


def normalize(name):
    # Collapse all whitespace runs to a single space, trim ends, casefold.
    return re.sub(r"\s+", " ", name).strip().casefold()


def main():
    if len(sys.argv) < 2:
        sys.stderr.write("usage: solution.py <input.csv>\n")
        return 2

    path = sys.argv[1]
    totals = {}  # normalized name -> summed quantity

    with open(path, "r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)

        # Map header names to canonical keys so column order/spacing is tolerated.
        fieldmap = {}
        if reader.fieldnames:
            for fn in reader.fieldnames:
                if fn is not None:
                    fieldmap[fn.strip()] = fn
        item_key = fieldmap.get("item")
        qty_key = fieldmap.get("quantity")

        for row in reader:
            raw = row.get(item_key)
            if raw is None:
                continue
            name = normalize(raw)
            if not name:
                continue

            qraw = row.get(qty_key)
            if qraw is None:
                qraw = ""
            qraw = qraw.strip()
            if qraw == "":
                qty = 1
            else:
                qty = int(qraw, 10)

            totals[name] = totals.get(name, 0) + qty

    result = [{"item": n, "quantity": totals[n]} for n in sorted(totals)]
    sys.stdout.write(json.dumps(result, ensure_ascii=False))
    sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
